// Builds the two generated files in this repository.
// 1. dist/peoplesoft-sql-lab.html, the whole lab in a single file.
// 2. oracle/peoplesoft_lab_oracle.sql, the same data for a real Oracle database.
// Usage: node tools/build.js
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const PSSchema = require(path.join(root, 'js', 'schema.js'));
const PSSeed = require(path.join(root, 'js', 'seed.js'));

// Read a file from the repository as text.
function read(rel) { return fs.readFileSync(path.join(root, rel), 'utf8'); }

// Inline the stylesheet and every script into one HTML file.
function buildStandalone() {
  let html = read('index.html');
  html = html.replace('<link rel="stylesheet" href="css/style.css">', function () {
    return '<style>\n' + read('css/style.css') + '</style>';
  });
  html = html.replace(/<script src="([^"]+)"><\/script>/g, function (m, src) {
    return '<script>\n' + read(src).replace(/<\/script/gi, '<\\/script') + '\n</script>';
  });
  fs.mkdirSync(path.join(root, 'dist'), { recursive: true });
  fs.writeFileSync(path.join(root, 'dist', 'peoplesoft-sql-lab.html'), html);
  return html.length;
}

// Format one value as an Oracle literal.
function literal(value, type) {
  if (value === null) return 'NULL';
  if (PSSchema.isDate(type)) return "DATE '" + value + "'";
  if (typeof value === 'number') return String(value === 0 ? 0 : value);
  return "'" + String(value).replace(/'/g, "''") + "'";
}

// Write the Oracle script: drop, create, insert, commit.
function buildOracle() {
  const data = PSSeed.build();
  const out = [];
  out.push('-- PeopleSoft SQL Lab practice schema for a real Oracle database.');
  out.push('-- Generated by tools/build.js. Do not edit by hand.');
  out.push('-- Run it in an empty practice schema, never in a real PeopleSoft database.');
  out.push('-- The lab treats ' + PSSeed.DEFAULT_LAB_DATE + ' as today. On real Oracle, SYSDATE is the real date.');
  out.push('');
  out.push('SET DEFINE OFF;');
  out.push('');
  PSSchema.tables.forEach(function (t) {
    out.push('BEGIN EXECUTE IMMEDIATE \'DROP TABLE ' + t.name + ' PURGE\'; EXCEPTION WHEN OTHERS THEN NULL; END;');
    out.push('/');
  });
  out.push('');
  let rows = 0;
  PSSchema.tables.forEach(function (t) {
    out.push(PSSchema.ddl(t) + ';');
    out.push(PSSchema.keyIndex(t) + ';');
    out.push('');
    data[t.name].forEach(function (row) {
      rows++;
      out.push('INSERT INTO ' + t.name + ' VALUES (' + row.map(function (v, i) { return literal(v, t.cols[i][1]); }).join(', ') + ');');
    });
    out.push('COMMIT;');
    out.push('');
  });
  fs.mkdirSync(path.join(root, 'oracle'), { recursive: true });
  fs.writeFileSync(path.join(root, 'oracle', 'peoplesoft_lab_oracle.sql'), out.join('\n'));
  return rows;
}

const size = buildStandalone();
const rows = buildOracle();
console.log('dist/peoplesoft-sql-lab.html written, ' + Math.round(size / 1024) + ' KB');
console.log('oracle/peoplesoft_lab_oracle.sql written, ' + rows + ' rows');
